INSERT INTO scientific_claims (id, claim_text_de, claim_text_en, claim_text_ru, evidence_status)
VALUES
  ('11111111-1111-4111-8111-111111111111',
   'H₂ neutralisiert in Zell- und Tiermodellen selektiv Hydroxylradikale.',
   'In cell and animal models H₂ selectively neutralizes hydroxyl radicals.',
   'В клеточных и животных моделях H₂ избирательно нейтрализует гидроксил-радикалы.',
   'high_consensus'::evidence_level),
  ('55555555-5555-4555-8555-555555550001',
   'Aufgrund seiner geringen Molmasse durchdringt H₂ in Tiermodellen die Blut-Hirn-Schranke.',
   'Due to its low molecular mass, H₂ crosses the blood-brain barrier in animal models.',
   'В животных моделях H₂ благодаря малой молекулярной массе проникает через гематоэнцефалический барьер.',
   'high_consensus'::evidence_level),
  ('55555555-5555-4555-8555-555555550002',
   'In einer Pilotstudie an Elite-Athleten ging HRW mit niedrigerem Blutlaktat nach Belastung einher.',
   'In a pilot study of elite athletes, HRW was associated with lower post-exercise blood lactate.',
   'В пилотном исследовании на элитных спортсменах H₂-вода сопровождалась более низким лактатом в крови после нагрузки.',
   'preliminary_promising'::evidence_level),
  ('22222222-2222-4222-8222-222222222222',
   'H₂ verbessert nachweislich Sportleistung und Regeneration beim Menschen.',
   'H₂ demonstrably improves exercise performance and recovery in humans.',
   'H₂ доказанно улучшает спортивные показатели и восстановление у человека.',
   'insufficient_data'::evidence_level),
  ('55555555-5555-4555-8555-555555550003',
   'H₂-Wasser verbesserte in kleinen Humanstudien Marker des oxidativen Stresses bei potenziellem metabolischem Syndrom.',
   'In small human studies, HRW improved oxidative-stress markers in potential metabolic syndrome.',
   'В малых исследованиях на людях H₂-вода улучшала маркеры окислительного стресса при потенциальном метаболическом синдроме.',
   'preliminary_promising'::evidence_level),
  ('55555555-5555-4555-8555-555555550004',
   'Eine kleine RCT (n=36) beschrieb verbesserte Lipid- und Oxidationsmarker bei Typ-2-Diabetes unter H₂-Wasser.',
   'A small RCT (n=36) described improved lipid and oxidation markers in type 2 diabetes with HRW.',
   'Малое РКИ (n=36) описало улучшение липидных и окислительных маркеров при диабете 2 типа на фоне H₂-воды.',
   'preliminary_promising'::evidence_level),
  ('55555555-5555-4555-8555-555555550005',
   'Eine niedrige Magnesiumzufuhr ist verbreitet und wird mit chronischen Erkrankungen assoziiert.',
   'Low magnesium intake is common and associated with chronic disease.',
   'Пониженное потребление магния распространено и ассоциировано с хроническими заболеваниями.',
   'high_consensus'::evidence_level),
  ('33333333-3333-4333-8333-333333333333',
   'Magnesium ist an Muskelkontraktion und Nervenreizleitung beteiligt (Essenzialität ist gesichert).',
   'Magnesium participates in muscle contraction and nerve signaling (essentiality is established).',
   'Магний участвует в сокращении мышц и нервной проводимости (эссенциальность доказана).',
   'high_consensus'::evidence_level),
  ('55555555-5555-4555-8555-555555550006',
   'Im ischämischen Mausmodell verringerte H₂-Inhalation das Hirninfarktvolumen.',
   'In a mouse ischemia model, H₂ inhalation reduced cerebral infarct volume.',
   'В модели ишемии у мышей ингаляция H₂ уменьшала объём инфаркта мозга.',
   'preliminary_promising'::evidence_level),
  ('55555555-5555-4555-8555-555555550007',
   'Die gelöste H₂-Konzentration ist methodeabhängig und nimmt mit Zeit, Wärme und Bewegung ab.',
   'Dissolved H₂ concentration depends on the method and decays with time, heat and agitation.',
   'Растворённая концентрация H₂ зависит от метода и снижается со временем, при нагреве и встряхивании.',
   'high_consensus'::evidence_level),
  ('55555555-5555-4555-8555-555555550008',
   'Hyperbarische H₂-Gemische wurden seit den 1940ern in der Tiefseetauchforschung erprobt.',
   'Hyperbaric H₂ mixtures have been tested in deep-diving research since the 1940s.',
   'Гипербарические смеси с H₂ применялись в глубоководных исследованиях с 1940-х годов.',
   'high_consensus'::evidence_level),
  ('55555555-5555-4555-8555-555555550009',
   'In kleinen Humanstudien zeigte H₂-Wasser ein bislang günstiges Verträglichkeitsprofil.',
   'In small human studies, HRW showed a favorable tolerability profile so far.',
   'В малых исследованиях на людях H₂-вода показала благоприятный профиль переносимости.',
