INSERT INTO encyclopedia_articles (slug, lang, title, summary, content_markdown, category, author_name, last_reviewed_at, is_published)
VALUES
  ('h2-antioxidant-mechanism', 'de',
   'Selektive Antioxidanzien: der Mechanismus hinter H₂',
   'Warum H₂ Hydroxylradikale bevorzugt neutralisiert und nützliche Signalstoffe schont — und welche Rolle die Blut-Hirn-Schranke spielt.',
   'Freie Radikale sind keine Einheitsklasse: Der Hydroxylradikal (•OH) gilt als die reaktivste Sauerstoffspezies im Organismus, während Wasserstoffperoxid oder Stickoxid (NO) als Signalstoffe wichtige Aufgaben erfüllen. Ein „gutes“ Antioxidans müsste also selektiv wirken — genau diese Selektivität wurde für molekularen Wasserstoff beschrieben.\n\nDie Grundlagenarbeit von Ohsawa und Kollegen (Nature Medicine, 2007) zeigte in Zellkulturen und im Tiermodell, dass gelöstes H₂ Hydroxylradikale effizient abfängt, während andere reaktive Spezies weitgehend unbeeinflusst bleiben. Übersichtsarbeiten (Ohta 2015) ordnen ein: Der Mechanismus umfasst vermutlich auch die Modulation von Zellsignalwegen — H₂ wirkt also nicht als simple Radikalfalle.\n\nBemerkenswert ist die Verteilung: Aufgrund seiner geringen Molmasse diffundiert H₂ rasch in Gewebe; in Tiermodellen wurde es auch hinter der Blut-Hirn-Schranke nachgewiesen. Das macht das Molekül für Forschungsfragen rund um das Gehirn besonders interessant.\n\nZur Einordnung: Selektivität ist im Labor gut messbar; am Menschen hängt der Effekt einer H₂-Quelle von Konzentration, Aufnahme und Stoffwechsel ab. Labordaten ersetzen keine klinische Wirksamkeit — dafür sind gezielte Humanstudien nötig.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-antioxidant-mechanism', 'en',
   'Selective antioxidants: the mechanism behind H₂',
   'Why H₂ preferentially neutralizes hydroxyl radicals and spares useful signaling molecules — and where the blood-brain barrier comes in.',
   'Free radicals are not a uniform class: the hydroxyl radical (•OH) is considered the most reactive oxygen species in the body, while hydrogen peroxide or nitric oxide (NO) fulfill signaling roles. A “good” antioxidant would have to act selectively — and exactly that selectivity was described for molecular hydrogen.\n\nThe foundational work by Ohsawa and colleagues (Nature Medicine, 2007) showed in cell cultures and animal models that dissolved H₂ efficiently scavenges hydroxyl radicals while largely leaving other reactive species untouched. Review literature (Ohta 2015) adds nuance: the mechanism likely also involves modulation of cell signaling pathways — H₂ does not act as a simple radical trap.\n\nRemarkable is the distribution: due to its low molecular mass, H₂ diffuses rapidly into tissue; in animal models it was also detected behind the blood-brain barrier. That makes the molecule particularly interesting for research questions around the brain.\n\nFor context: selectivity is well measurable in the lab; in humans, the effect of an H₂ source depends on concentration, intake and metabolism. Laboratory data do not replace clinical effectiveness — targeted human studies are needed for that.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-antioxidant-mechanism', 'ru',
   'Селективные антиоксиданты: механизм за H₂',
   'Почему H₂ избирательно нейтрализует гидроксил-радикалы и щадит полезные сигнальные молекулы — и как здесь работает гематоэнцефалический барьер.',
   'Свободные радикалы — не однородный класс: гидроксил-радикал (•OH) считается самой реакционноспособной кислородной частицей в организме, тогда как пероксид водорода или оксид азота (NO) выполняют сигнальные функции. «Хорошему» антиоксиданту следовало бы действовать избирательно — именно такая селективность была описана для молекулярного водорода.\n\nФундаментальная работа Ohsawa и коллег (Nature Medicine, 2007) показала в клеточных культурах и на животных моделях, что растворённый H₂ эффективно перехватывает гидроксил-радикалы, почти не затрагивая другие реактивные частицы. Обзоры (Ohta 2015) уточняют: механизм, вероятно, включает и модуляцию клеточных сигнальных путей — H₂ не является простой «радикальной ловушкой».\n\nПримечательно распределение: из-за малой молекулярной массы H₂ быстро диффундирует в ткани; на животных моделях его обнаруживали и за гематоэнцефалическим барьером. Это делает молекулу особенно интересной для исследований мозга.\n\nДля понимания: селективность хорошо измерима в лаборатории; у человека эффект H₂-источника зависит от концентрации, способа приёма и метаболизма. Лабораторные данные не заменяют клиническую эффективность — для этого нужны целевые исследования на людях.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-exercise-recovery', 'de',
   'H₂ und Sport: Laktat, Ermüdung und die Pilotstudie an Spitzensportlern',
   'Was die doppelblinde Crossover-Pilotstudie an zehn Elite-Athleten zu Laktat und Muskelermüdung fand — und warum Pilotdaten kein Beweis sind.',
   'Intensives Training erhöht Laktat und oxidativen Stress. Da H₂ selektiv besonders aggressive Radikale neutralisiert, lag die Forschungsfrage nahe: Beeinflusst hydrogenreiches Wasser (HRW) Erholung und Ermüdung?\n\nAoki und Kollegen (Medical Gas Research, 2012) untersuchten dies in einer randomisierten, doppelblinden, placebokontrollierten Crossover-Pilotstudie mit zehn männlichen Elite-Athleten: 1,5 Liter HRW täglich über zwei Wochen. Vor dem Belastungstest getrunkenes HRW ging mit niedrigerem Blutlaktat und einem besseren isometrischen Drehmoment einher.\n\nDie Autoren ordnen selbst als Pilotstudie ein: kleine Stichprobe, spezifisches Kollektiv (Spitzensportler), kurze Dauer. Das Ergebnis ist ein Hinweis zur Hypothesengenerierung — kein Wirksamkeitsnachweis für die Allgemeinbevölkerung.\n\nPraktisch heißt das: Wer HRW im Sportkontext ausprobieren möchte, tut das als dokumentierter Selbstversuch mit realistischen Erwartungen. Die Datenlage wächst; übergreifende Auswertungen bleiben derzeit zurückhaltend.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-exercise-recovery', 'en',
   'H₂ and sport: lactate, fatigue and the pilot study in elite athletes',
   'What the double-blind crossover pilot in ten elite athletes found on lactate and muscle fatigue — and why pilot data are not proof.',
   'Intense exercise raises lactate and oxidative stress. Since H₂ selectively neutralizes the most aggressive radicals, the research question was obvious: does hydrogen-rich water (HRW) affect recovery and fatigue?\n\nAoki and colleagues (Medical Gas Research, 2012) examined this in a randomized, double-blind, placebo-controlled crossover pilot with ten male elite athletes: 1.5 liters of HRW daily for two weeks. HRW consumed before the exercise test was associated with lower blood lactate and better isometric peak torque.\n\nThe authors themselves frame it as a pilot: small sample, specific population (elite athletes), short duration. The result is a hypothesis-generating signal — not proof of effectiveness for the general population.\n\nIn practice: if you want to try HRW in a sports context, treat it as a documented self-experiment with realistic expectations. The evidence base is growing; aggregate analyses remain cautious for now.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-exercise-recovery', 'ru',
   'H₂ и спорт: лактат, усталость и пилотное исследование на элитных спортсменах',
   'Что показало двойное слепое перекрёстное пилотное исследование на десяти спортсменах: лактат, мышечная усталость — и почему пилотные данные не являются доказательством.',
   'Интенсивные тренировки повышают лактат и окислительный стресс. Поскольку H₂ избирательно нейтрализует самые агрессивные радикалы, исследовательский вопрос напрашивался: влияет ли обогащённая водородом вода (HRW) на восстановление и усталость?\n\nAoki и коллеги (Medical Gas Research, 2012) проверили это в рандомизированном двойном слепом плацебо-контролируемом перекрёстном пилотном исследовании на десяти мужчинах-спортсменах элитного уровня: 1,5 литра HRW ежедневно в течение двух недель. HRW, выпитый перед тестовой нагрузкой, сопровождался более низким лактатом в крови и лучшим изометрическим крутящим моментом.\n\nАвторы сами определяют работу как пилотную: малая выборка, специфический контингент (элитные спортсмены), короткий срок. Результат — сигнал для генерации гипотез, а не доказательство эффективности для широкой популяции.\n\nПрактический смысл: если хочется попробовать HRW в спортивном контексте — это документированный самоэксперимент с реалистичными ожиданиями. Данные накапливаются, но обобщающие анализы пока остаются сдержанными.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-metabolic-syndrome', 'de',
   'Metabolisches Syndrom: zwei Humanstudien zu oxidativem Stress und Lipiden',
   'Open-Label-Pilot (n=20) und randomisierte Doppelblindstudie (n=68) zu H₂-Wasser bei potenziellem metabolischem Syndrom — Ergebnisse und Grenzen.',
   'Das metabolische Syndrom (Bauchumfang, Blutfette, Blutzucker, Blutdruck) geht mit erhöhtem oxidativem Stress einher. H₂ wurde deshalb als unterstützender Forschungsgegenstand untersucht — nicht als Therapie.\n\nNakao und Kollegen (2010) berichteten in einem offenen Pilot mit 20 Personen über acht Wochen HRW: Das Antioxidans-Enzym SOD stieg, der Oxidationsmarker TBARS sank; zudem zeigten sich HDL-Verbesserungen. Ohne Placebogruppe sind solche Ergebnisse anfällig für Erwartungs- und Moduseffekte.\n\nSong und Kollegen (2013, Journal of Lipid Research) randomisierten 68 Personen mit potenziellem metabolischem Syndrom zu HRW oder Placebo: Die HRW-Gruppe zeigte niedrigere LDL-Cholesterin-Werte und eine verbesserte HDL-Funktion.\n\nEinordnung: zwei kleine Studien mit konsistenter Richtung — ein Trend, keine Leitlinien-Evidenz. Lebensstil (Bewegung, Ernährung) bleibt die Basis; H₂-Wasser ersetzt sie nicht.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-metabolic-syndrome', 'en',
   'Metabolic syndrome: two human studies on oxidative stress and lipids',
   'Open-label pilot (n=20) and randomized double-blind trial (n=68) of HRW in potential metabolic syndrome — results and limits.',
   'Metabolic syndrome (waist circumference, blood lipids, glucose, blood pressure) goes along with elevated oxidative stress. H₂ was therefore studied as a research subject — not as a therapy.\n\nNakao and colleagues (2010) reported in an open-label pilot with 20 participants on eight weeks of HRW: the antioxidant enzyme SOD increased, the oxidation marker TBARS decreased; HDL also improved. Without a placebo group, such results are vulnerable to expectation and mode effects.\n\nSong and colleagues (2013, Journal of Lipid Research) randomized 68 people with potential metabolic syndrome to HRW or placebo: the HRW group showed lower LDL-cholesterol values and improved HDL function.\n\nAssessment: two small studies pointing in a consistent direction — a trend, not guideline-grade evidence. Lifestyle (movement, nutrition) remains the foundation; HRW does not replace it.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-metabolic-syndrome', 'ru',
   'Метаболический синдром: два исследования на людях — окислительный стресс и липиды',
   'Открытый пилот (n=20) и рандомизированное двойное слепое исследование (n=68) H₂-воды при потенциальном метаболическом синдроме — результаты и ограничения.',
   'Метаболический синдром (окружность талии, липиды крови, глюкоза, давление) сопровождается повышенным окислительным стрессом. H₂ исследовали как вспомогательный объект науки — не как терапию.\n\nNakao и коллеги (2010) сообщили в открытом пилоте с 20 участниками о восьми неделях HRW: антиоксидантный фермент SOD вырос, маркер окисления TBARS снизился; также улучшился HDL. Без плацебо-группы такие результаты уязвимы для эффектов ожидания.\n\nSong и коллеги (2013, Journal of Lipid Research) рандомизировали 68 человек с потенциальным метаболическим синдромом в группы HRW или плацебо: в группе HRW снизился ЛПНП-холестерин и улучшилась функция ЛПВП.\n\nОценка: два небольших исследования с согласованным направлением — это тренд, а не доказательная база клинических рекомендаций. Образ жизни (движение, питание) остаётся основой; H₂-вода его не заменяет.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-glucose-type2-diabetes', 'de',
   'Typ-2-Diabetes: die kleine randomisierte Studie von 2008',
   '36 Patienten, 8 Wochen, H₂-Wasser: verbesserte Lipid- und Oxidationsmarker — und warum eine einzige kleine RCT keine Therapieempfehlung trägt.',
   'Kajiyama und Kollegen (Nutrition Research, 2008) untersuchten als eine der frühesten Humanstudien 36 Personen mit Typ-2-Diabetes oder gestörter Glucosetoleranz: randomisiert, doppelblind, placebokontrolliert, acht Wochen H₂-Wasser.\n\nBeschrieben wurden Verbesserungen beim Lipidprofil und bei Oxidationsmarkern; der HOMA-Index zeigte in Subgruppen aufwärtsgerichtete Tendenzen. Die Autoren sprachen bewusst vorsichtig von einer möglichen präventiven Rolle.\n\nSeither sind weitere Studien und Auswertungen zu Blutzucker- und Lipidmarkern erschienen. Das Gesamtbild bleibt heterogen: kleine Stichproben, unterschiedliche H₂-Konzentrationen, verschiedene Dauer.\n\nWichtig: Für Menschen mit Diabetes ändert H₂-Wasser nichts an Medikamenten, Blutzuckerselbstmessung oder ärztlicher Begleitung. Es ist ein Forschungsthema — keine Therapie und kein Ersatz für Behandlung.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-glucose-type2-diabetes', 'en',
   'Type 2 diabetes: the small randomized trial from 2008',
   '36 patients, 8 weeks, HRW: improved lipid and oxidation markers — and why one small RCT carries no treatment recommendation.',
   'Kajiyama and colleagues (Nutrition Research, 2008) — one of the earliest human studies: 36 people with type 2 diabetes or impaired glucose tolerance, randomized, double-blind, placebo-controlled, eight weeks of HRW.\n\nImprovements were described in the lipid profile and oxidation markers; the HOMA index showed upward tendencies in subgroups. The authors deliberately spoke cautiously of a possible preventive role.\n\nSince then, further studies and analyses on glucose and lipid markers have appeared. The overall picture remains heterogeneous: small samples, different H₂ concentrations, varying durations.\n\nImportant: for people with diabetes, HRW changes nothing about medication, glucose self-monitoring or medical care. It is a research topic — not a therapy and not a substitute for treatment.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-glucose-type2-diabetes', 'ru',
   'Диабет 2 типа: небольшое рандомизированное исследование 2008 года',
   '36 пациентов, 8 недель, H₂-вода: улучшение липидных и окислительных маркеров — и почему одно малое РКИ не даёт терапевтической рекомендации.',
   'Kajiyama и коллеги (Nutrition Research, 2008) — одно из первых исследований на людях: 36 человек с диабетом 2 типа или нарушенной толерантностью к глюкозе, рандомизация, двойное слепое плацебо-контроль, восемь недель H₂-воды.\n\nОписаны улучшения липидного профиля и маркеров окисления; индекс HOMA в подгруппах показал восходящие тенденции. Авторы осторожно говорили о возможной профилактической роли.\n\nС тех пор вышли новые исследования и анализы по глюкозным и липидным маркерам. Общая картина остаётся неоднородной: малые выборки, разные концентрации H₂, разная длительность.\n\nВажно: для людей с диабетом H₂-вода не меняет ничего в приёме лекарств, самоконтроле глюкозы и наблюдении врача. Это исследовательская тема — не терапия и не замена лечения.',
   'studies', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('magnesium-intake-basics', 'de',
   'Magnesiumversorgung: Bedarf, Versorgungslage und typische Zeichen',
   'Referenzwerte, häufige Risikogruppen für niedrige Magnesiumversorgung — und warum Symptome wie Krämpfe mehrdeutig sind.',
   'Referenzwerte für Magnesium liegen für Erwachsene je nach Alter und Geschlecht grob bei 300–400 mg pro Tag. Der Mineralstoff ist an über 300 Enzymreaktionen beteiligt — von Muskel- und Nervenfunktion bis Energiestoffwechsel.\n\nEin umfassender Review (Gröber und Kollegen, Nutrients, 2015) fasst zusammen: Eine niedrige Magnesiumzufuhr ist in der Allgemeinbevölkerung nicht selten. Risikogruppen umfassen u. a. Menschen mit einseitiger Ernährung, hohem Alkoholkonsum, chronischem Durchfall oder Einnahme bestimmter Medikamente (z. B. Diuretika, Protonenpumpeninhibitoren).\n\nSymptome wie nächtliche Wadenkrämpfe, Muskelzuckungen oder Müdigkeit sind mehrdeutig — sie haben viele mögliche Ursachen. Ein tatsächlicher Magnesiummangel wird im Labor geprüft, nicht am Gefühl festgemacht.\n\nPraxis: Eine ballaststoffreiche Ernährung (Vollkorn, Hülsenfrüchte, Nüsse, grünes Gemüse, magnesiumreiches Mineralwasser) deckt den Bedarf meist. Supplemente ergänzen gezielt — zu hohe Dosen wirken abführend, „mehr“ ist nicht automatisch „besser“.',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('magnesium-intake-basics', 'en',
   'Magnesium intake: requirements, status and typical signs',
   'Reference values, common risk groups for low magnesium status — and why symptoms like cramps are ambiguous.',
   'Magnesium reference values for adults are roughly 300–400 mg per day depending on age and sex. The mineral participates in over 300 enzymatic reactions — from muscle and nerve function to energy metabolism.\n\nA comprehensive review (Gröber and colleagues, Nutrients, 2015) summarizes: low magnesium intake is not uncommon in the general population. Risk groups include people with one-sided diets, high alcohol consumption, chronic diarrhea, or use of certain medications (e.g., diuretics, proton pump inhibitors).\n\nSymptoms like nightly calf cramps, muscle twitching or fatigue are ambiguous — they have many possible causes. An actual magnesium deficiency is verified in the lab, not judged by feeling.\n\nPractice: a fiber-rich diet (whole grains, legumes, nuts, green vegetables, mineral water high in magnesium) usually covers the need. Supplements complement selectively — excessive doses have a laxative effect, “more” is not automatically “better”.',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('magnesium-intake-basics', 'ru',
   'Обеспеченность магнием: потребность, дефициты и типичные признаки',
   'Референсные значения, частые группы риска по низкой обеспеченности магнием — и почему симптомы вроде судорог неоднозначны.',
   'Референсные значения магния для взрослых — примерно 300–400 мг в день в зависимости от возраста и пола. Минерал участвует более чем в 300 ферментных реакциях — от мышечной и нервной функции до энергетического обмена.\n\nОбзор (Gröber и коллеги, Nutrients, 2015) резюмирует: пониженное потребление магния в общей популяции встречается нередко. Группы риска — люди с однообразным питанием, высоким потреблением алкоголя, хронической диареей или приёмом определённых препаратов (например, диуретиков, ингибиторов протонной помпы).\n\nСимптомы вроде ночных судорог икр, подёргиваний мышц или усталости неоднозначны — у них много возможных причин. Реальный дефицит магния подтверждается лабораторно, а не «по ощущениям».\n\nПрактика: питание, богатое клетчаткой (цельнозерновые, бобовые, орехи, зелёные овощи, минеральная вода с высоким содержанием магния), обычно покрывает потребность. Добавки — адресно: избыточные дозы слабят, «больше» не значит «лучше».',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-brain-neuroprotection', 'de',
   'H₂ und das Gehirn: was Tiermodelle zeigen — und was noch fehlt',
   'Von der ischämischen Maus bis zur Blut-Hirn-Schranke: neuroprotektive Signale im Tiermodell, kleine Humanpiloten — und die Lücke dazwischen.',
   'Das Gehirn ist oxidativ besonders verwundbar: hoher Sauerstoffumsatz, lipidreiche Membranen. Für H₂ spannend ist die Kombination aus Selektivität und kleiner Molekülmasse — in Tiermodellen überschreitet H₂ die Blut-Hirn-Schranke.\n\nDie Arbeit von Ohsawa und Kollegen (2007) zeigte im ischämischen Mausmodell: Inhalation von H₂-Gas verringerte das Hirninfarktvolumen deutlich. Übersichtsarbeiten (Ohta 2015) listen seither zahlreiche Tiermodelle — Ischämie, Entzündung, degenerative Ansätze — mit positiven Signalen.\n\nBeim Menschen ist die Lage dünn: einzelne kleine Pilotstudien deuten auf Machbarkeit und Verträglichkeit hin, aber große randomisierte Studien mit harten Endpunkten fehlen bislang.\n\nFazit: Neuroprotektion durch H₂ ist eine biologisch plausible Tiermodell-These. Eine Schutzwirkung am Menschen ist damit nicht bewiesen — hier wären registrierte randomisierte Studien nötig.',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-brain-neuroprotection', 'en',
   'H₂ and the brain: what animal models show — and what is missing',
   'From the ischemic mouse to the blood-brain barrier: neuroprotective signals in animal models, small human pilots — and the gap in between.',
   'The brain is especially vulnerable to oxidation: high oxygen turnover, lipid-rich membranes. For H₂, the combination of selectivity and low molecular mass is intriguing — in animal models H₂ crosses the blood-brain barrier.\n\nThe work by Ohsawa and colleagues (2007) showed in an ischemic mouse model: inhalation of H₂ gas markedly reduced cerebral infarct volume. Review literature (Ohta 2015) lists numerous animal models since — ischemia, inflammation, degenerative approaches — with positive signals.\n\nIn humans the picture is thin: individual small pilot studies point to feasibility and tolerability, but large randomized trials with hard endpoints are still missing.\n\nConclusion: neuroprotection via H₂ is a biologically plausible animal-model thesis. A protective effect in humans is not proven by it — registered randomized trials would be needed.',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-brain-neuroprotection', 'ru',
   'H₂ и мозг: что показывают животные модели — и чего ещё не хватает',
   'От ишемической мыши до гематоэнцефалического барьера: нейропротективные сигналы в животных моделях, малые пилоты на людях — и пропасть между ними.',
   'Мозг особенно уязвим к окислению: высокое потребление кислорода, мембраны, богатые липидами. Для H₂ интересна комбинация селективности и малой молекулярной массы — на животных моделях H₂ преодолевает гематоэнцефалический барьер.\n\nРабота Ohsawa и коллег (2007) показала на ишемической модели мышей: ингаляция H₂-газа заметно уменьшала объём инфаркта мозга. Обзоры (Ohta 2015) перечисляют с тех пор десятки моделей — ишемия, воспаление, дегенеративные подходы — с положительными сигналами.\n\nУ человека картина тонкая: отдельные малые пилотные исследования указывают на выполнимость и переносимость, но крупных рандомизированных исследований с жёсткими конечными точками до сих пор нет.\n\nВывод: нейропротекция через H₂ — биологически правдоподобная гипотеза из животных моделей. Защитный эффект у человека ею не доказан — здесь необходимы зарегистрированные рандомизированные исследования.',
   'human_biology', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-water-production', 'de',
   'H₂-Quellen im Vergleich: Tabletten, Elektrolyse-Flaschen und Generatoren',
   'Wie gelöster molekularer Wasserstoff entsteht, warum die Konzentration in ppm gemessen wird und weshalb sie mit der Zeit abnimmt.',
   'Gelöster molekularer Wasserstoff wird in ppm (Milligramm pro Liter) angegeben. Bei Normaldruck lösen sich theoretisch rund 1,6 mg H₂ pro Liter Wasser (Sättigung ≈ 1,6 ppm); praktische Werte hängen von der Erzeugungsmethode ab.\n\nElektrolyse-Flaschen spalten Wasser elektrolytisch — die erreichbare Konzentration hängt von Elektrodenqualität, Membran und Laufzeit ab. H₂-Tabletten nutzen die Reaktion von metallischem Magnesium mit Wasser: Mg + 2 H₂O → Mg(OH)₂ + H₂. Der Wasserstoff entsteht direkt im Getränk — zusammen mit gelöstem Magnesium.\n\nMessbar relevant: H₂ ist ein kleines, flüchtiges Molekül. Gelöstes Gas entweicht mit der Zeit — besonders bei Wärme, Bewegung und offenem Behälter. Frisch zubereitet trinken ist deshalb sinnvoll; Übersichtsarbeiten (Ohta 2015) diskutieren Konzentration und Dosis als Kerngrößen der Forschung.\n\nFür Kaufentscheidungen: Auf angegebene Konzentration (ppm), Messmethode und Materialqualität achten. Unabhängig gemessene Werte sind aussagekräftiger als Marketingzahlen.',
   'equipment', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-water-production', 'en',
   'H₂ sources compared: tablets, electrolysis bottles and generators',
   'How dissolved molecular hydrogen is produced, why concentration is measured in ppm and why it decays over time.',
   'Dissolved molecular hydrogen is specified in ppm (milligrams per liter). At normal pressure, roughly 1.6 mg of H₂ dissolves per liter of water (saturation ≈ 1.6 ppm); practical values depend on the production method.\n\nElectrolysis bottles split water electrolytically — the achievable concentration depends on electrode quality, membrane and runtime. H₂ tablets use the reaction of metallic magnesium with water: Mg + 2 H₂O → Mg(OH)₂ + H₂. The hydrogen is generated directly in the drink — together with dissolved magnesium.\n\nMeasurably relevant: H₂ is a small, volatile molecule. Dissolved gas escapes over time — especially with heat, agitation and open containers. Drinking freshly prepared therefore makes sense; review literature (Ohta 2015) discusses concentration and dose as core parameters of the research.\n\nFor purchase decisions: look at the stated concentration (ppm), the measurement method and material quality. Independently measured values are more informative than marketing figures.',
   'equipment', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-water-production', 'ru',
   'Источники H₂ в сравнении: таблетки, бутылки-электролизёры и генераторы',
   'Как образуется растворённый молекулярный водород, почему концентрацию измеряют в ppm и почему она со временем падает.',
   'Растворённый молекулярный водород измеряют в ppm (мг на литр). При нормальном давлении в воде теоретически растворяется около 1,6 мг H₂ на литр (насыщение ≈ 1,6 ppm); практические значения зависят от метода получения.\n\nБутылки с электролизом расщепляют воду электролитически — достижимая концентрация зависит от качества электродов, мембраны и времени работы. H₂-таблетки используют реакцию металлического магния с водой: Mg + 2 H₂O → Mg(OH)₂ + H₂. Водород образуется прямо в напитке — вместе с растворённым магнием.\n\nИзмеримо важно: H₂ — маленькое летучее вещество. Растворённый газ уходит со временем — особенно при нагреве, встряхивании и открытом сосуде. Поэтому пить стоит свежеприготовленным; обзоры (Ohta 2015) обсуждают концентрацию и дозу как ключевые параметры исследований.\n\nДля выбора: смотреть на заявленную концентрацию (ppm), метод измерения и качество материалов. Независимо измеренные значения информативнее маркетинговых цифр.',
   'equipment', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-safety-history', 'de',
   'Sicherheit und Geschichte: vom Tiefsee-Gas zur Forschungstablette',
   'Hyperbarischer Wasserstoff seit den 1940ern, die Science-Arbeit von 1975 und das Verträglichkeitsbild moderner Humanpiloten.',
   'Wasserstoffatmung ist keine Novität: In der Tiefseetauchforschung wurden Wasserstoff-Sauerstoff-Gemische bereits seit Mitte des 20. Jahrhunderts erprobt, um Dekompressionseffekte zu reduzieren. Menschen atmeten also schon lange kontrolliert H₂-haltige Gemische — unter Aufsicht und in kontrollierter Umgebung.\n\nDen frühesten therapeutischen Hinweis in der Fachliteratur lieferten Dole und Kollegen (Science, 1975): Hyperbarische H₂-Atmung ließ Hauttumoren bei Mäusen schrumpfen — ein Tiermodell, heute als historischer Meilenstein eingeordnet.\n\nModerne Humanpiloten (u. a. Nakao 2010, Aoki 2012) berichten bei H₂-Wasser von einem bislang günstigen Verträglichkeitsprofil; schwere unerwünschte Ereignisse wurden in den kleinen Studien nicht beschrieben. Systematische Sicherheitsdatenbanken für Supplemente bleiben dennoch begrenzt.\n\nGrenzen bleiben: Schwangere, Menschen mit schweren Erkrankungen oder Medikation besprechen H₂-Anwendung mit ihrer Ärztin oder ihrem Arzt. Und: Ein günstiges Sicherheitsprofil ist kein Wirksamkeitsbeweis — beides getrennt denken.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-safety-history', 'en',
   'Safety and history: from deep-sea gas to the research tablet',
   'Hyperbaric hydrogen since the 1940s, the 1975 Science paper and the tolerability picture of modern human pilots.',
   'Hydrogen breathing is not new: in deep-diving research, hydrogen-oxygen mixtures have been tested since the mid-20th century to reduce decompression effects. Humans have long breathed controlled H₂-containing mixtures — supervised and in controlled environments.\n\nThe earliest therapeutic hint in the scientific literature came from Dole and colleagues (Science, 1975): hyperbaric H₂ breathing shrank skin tumors in mice — an animal model, today regarded as a historical milestone.\n\nModern human pilots (e.g., Nakao 2010, Aoki 2012) report a so-far favorable tolerability profile for HRW; serious adverse events were not described in the small studies. Systematic safety databases for supplements nevertheless remain limited.\n\nLimits remain: pregnant people, those with serious illnesses or on medication should discuss H₂ use with their doctor. And: a favorable safety profile is not proof of effectiveness — keep the two separate.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE),
  ('h2-safety-history', 'ru',
   'Безопасность и история: от глубоводного газа к исследовательской таблетке',
   'Гипербарический водород с 1940-х, работа в Science 1975 года и картина переносимости в современных исследованиях на людях.',
   'Дыхание водородом — не новинка: в исследованиях глубоководного погружения смеси водорода и кислорода испытывали с середины XX века, чтобы снизить декомпрессионные эффекты. Люди давно дышали контролируемыми смесями с H₂ — под наблюдением и в контролируемой среде.\n\nСамое раннее терапевтическое упоминание в научной литературе — Dole и коллеги (Science, 1975): гипербарическая ингаляция H₂ уменьшала кожные опухоли у мышей — животная модель, сегодня считающаяся историческим рубежом.\n\nСовременные пилотные исследования на людях (в т.ч. Nakao 2010, Aoki 2012) сообщают о пока благоприятном профиле переносимости H₂-воды; серьёзные нежелательные события в малых исследованиях не описывались. Систематические базы данных безопасности для добавок всё же ограничены.\n\nОграничения остаются: беременным, людям с тяжёлыми заболеваниями или на медикаментах — обсуждать применение H₂ с врачом. И: благоприятный профиль безопасности не является доказательством эффективности — эти вещи нужно разделять.',
   'fundamentals', 'Redaktion RevolutTIME', '2026-11-11', TRUE)
ON CONFLICT (slug, lang) DO NOTHING;

